-- Tambahan nilai akademik_json.praktik agar kriteria praktik dapat dihitung.
-- Nilai ini bersifat default berbasis kategori alternatif; dapat disesuaikan lagi di aplikasi bila sekolah memiliki nilai praktik yang lebih rinci.
UPDATE `alternatives`
SET `akademik_json` = JSON_SET(
  `akademik_json`,
  '$.praktik',
  CASE
    WHEN `kategori` = 'praktik' THEN 90
    WHEN `kategori` = 'teknologi' THEN 60
    WHEN JSON_EXTRACT(`profil_tag_json`, '$.praktik') IS NOT NULL THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(`profil_tag_json`, '$.praktik')) AS UNSIGNED)
    WHEN `tujuan_karir` = 'kerja' THEN 50
    ELSE 35
  END
)
WHERE JSON_EXTRACT(`akademik_json`, '$.praktik') IS NULL;


-- Bobot sumber tag untuk matching non-akademik. Total = 1.0
ON DUPLICATE KEY UPDATE `weight` = VALUES(`weight`);


-- Skor kategori untuk mapped_key prestasi tambahan.
ON DUPLICATE KEY UPDATE sains=GREATEST(sains,VALUES(sains)), teknologi=GREATEST(teknologi,VALUES(teknologi)), sosial=GREATEST(sosial,VALUES(sosial)), bisnis=GREATEST(bisnis,VALUES(bisnis)), kreatif=GREATEST(kreatif,VALUES(kreatif)), praktik=GREATEST(praktik,VALUES(praktik)), agama=GREATEST(agama,VALUES(agama));


-- ============================================================
-- ROADMAP MASTER/STEP/DETAIL
-- ============================================================

SET NAMES utf8mb4;

-- ============================================================
-- ROADMAP SEED FIXED - sesuai entity backend sekarang
-- TIDAK memakai column alternative_id / headline / nama / target_role / kategori / tujuan_karir.
-- id_roadmap tetap disamakan dengan alternatives.id agar hasil SPK alternative/alternatif_id
-- bisa dipakai sebagai roadmap_id.
-- ============================================================

CREATE TABLE IF NOT EXISTS roadmap_master (
  id_roadmap INT AUTO_INCREMENT PRIMARY KEY,
  title VARCHAR(180) NOT NULL,
  description TEXT NULL,
  category VARCHAR(120) NULL,
  target_type ENUM('kuliah','kerja','wirausaha','umum') NOT NULL DEFAULT 'umum',
  recommended_for VARCHAR(120) NULL,
  is_active TINYINT NOT NULL DEFAULT 1,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  KEY idx_roadmap_master_active (is_active),
  KEY idx_roadmap_master_target (target_type),
  KEY idx_roadmap_master_category (category)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS roadmap_step (
  id_roadmap_step INT AUTO_INCREMENT PRIMARY KEY,
  id_roadmap INT NOT NULL,
  title VARCHAR(180) NOT NULL,
  description TEXT NULL,
  step_order INT NOT NULL DEFAULT 1,
  estimated_duration VARCHAR(80) NULL,
  output_target VARCHAR(180) NULL,
  is_active TINYINT NOT NULL DEFAULT 1,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  KEY idx_roadmap_step_master (id_roadmap, step_order)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS roadmap_step_detail (
  id_roadmap_step_detail INT AUTO_INCREMENT PRIMARY KEY,
  id_roadmap_step INT NOT NULL,
  title VARCHAR(180) NOT NULL,
  description TEXT NULL,
  reference_link TEXT NULL,
  reference_type VARCHAR(80) NULL,
  detail_order INT NOT NULL DEFAULT 1,
  is_active TINYINT NOT NULL DEFAULT 1,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  KEY idx_roadmap_step_detail_step (id_roadmap_step, detail_order)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), category=VALUES(category), target_type=VALUES(target_type), recommended_for=VALUES(recommended_for), is_active=VALUES(is_active);

