-- ============================================================
-- SKILLLENS SEED V8 - AKURASI SPK, MASTER TAG, BOBOT PRESTASI, DAN ROADMAP SUPPORT
-- Aman dijalankan ulang. Bagian ini memperbaiki data lama yang sebelumnya INSERT IGNORE.
-- ============================================================

SET NAMES utf8mb4;

ON DUPLICATE KEY UPDATE `value` = VALUES(`value`);

-- Bobot sumber tag. Minat dibuat paling kuat karena minat adalah sinyal arah utama siswa.
ON DUPLICATE KEY UPDATE `weight` = VALUES(`weight`);

-- Master tag alias dari label UI/user wording ke canonical mapped_key.
ON DUPLICATE KEY UPDATE mapped_key=VALUES(mapped_key), kategori_hint=VALUES(kategori_hint), sort_order=VALUES(sort_order), is_active=VALUES(is_active);

-- Skor kategori tag penting dibuat lebih tajam agar desain tidak kalah oleh tag sosial/hukum yang terlalu umum.
ON DUPLICATE KEY UPDATE sains=VALUES(sains), teknologi=VALUES(teknologi), sosial=VALUES(sosial), bisnis=VALUES(bisnis), kreatif=VALUES(kreatif), praktik=VALUES(praktik), agama=VALUES(agama);

-- Tabel pendukung bobot prestasi: tingkat lomba, posisi, dan jenis prestasi.
CREATE TABLE IF NOT EXISTS `prestasi_level_weights` (
  `level_key` VARCHAR(50) PRIMARY KEY,
  `label` VARCHAR(120) NOT NULL,
  `score` DOUBLE NOT NULL,
  `sort_order` INT NOT NULL DEFAULT 0,
  `is_active` TINYINT NOT NULL DEFAULT 1
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `prestasi_rank_weights` (
  `rank_key` VARCHAR(50) PRIMARY KEY,
  `label` VARCHAR(120) NOT NULL,
  `score` DOUBLE NOT NULL,
  `sort_order` INT NOT NULL DEFAULT 0,
  `is_active` TINYINT NOT NULL DEFAULT 1
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `prestasi_type_weights` (
  `type_key` VARCHAR(60) PRIMARY KEY,
  `label` VARCHAR(160) NOT NULL,
  `mapped_key` VARCHAR(120) NOT NULL,
  `kategori_hint` ENUM('sains','teknologi','sosial','bisnis','kreatif','praktik','agama') NOT NULL,
  `score` DOUBLE NOT NULL,
  `sort_order` INT NOT NULL DEFAULT 0,
  `is_active` TINYINT NOT NULL DEFAULT 1,
  KEY `idx_prestasi_type_mapped_key` (`mapped_key`),
  KEY `idx_prestasi_type_kategori` (`kategori_hint`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ON DUPLICATE KEY UPDATE label=VALUES(label), score=VALUES(score), sort_order=VALUES(sort_order), is_active=VALUES(is_active);

ON DUPLICATE KEY UPDATE label=VALUES(label), score=VALUES(score), sort_order=VALUES(sort_order), is_active=VALUES(is_active);

ON DUPLICATE KEY UPDATE label=VALUES(label), mapped_key=VALUES(mapped_key), kategori_hint=VALUES(kategori_hint), score=VALUES(score), sort_order=VALUES(sort_order), is_active=VALUES(is_active);

-- Pembobotan criteria V8. Total tiap profil = 1.0.
