-- Similarity groups tambahan. Hapus group V8 dulu supaya rerun tidak menumpuk.

-- Perbaikan alternatif desain/UI agar minat UI/UX/DKV benar-benar nyambung ke alternatif kuliah/kerja/wirausaha.
UPDATE `alternatives`
SET profil_tag_json = JSON_SET(COALESCE(profil_tag_json, JSON_OBJECT()),
  '$."ui ux"', 95, '$."figma"', 90, '$."wireframe"', 85, '$."prototype"', 85,
  '$."user research"', 80, '$."desain"', 100, '$."kreatif"', 95)
WHERE nama IN ('Desain Komunikasi Visual','Desain Produk','Desain Interior','Desain Multimedia','Desain Produk Industri','UI/UX Designer','Jasa UI/UX / Website','Kursus Desain Online','Frontend Developer','Mobile Developer','Rekayasa Perangkat Lunak','Jasa Pembuatan Website UMKM','Desainer Grafis','Brand Designer','Jasa Desain Grafis','Branding UMKM','Game Technology','Desain Game');

-- Tegaskan alternatif hukum tetap di jalur sosial/legal, bukan kreatif/desain.
UPDATE `alternatives`
SET profil_tag_json = JSON_SET(COALESCE(profil_tag_json, JSON_OBJECT()),
  '$."hukum"', 100, '$."legal"', 95, '$."debat"', 85, '$."public speaking"', 80, '$."sosial"', 90),
  kategori = 'sosial'
WHERE nama IN ('Ilmu Hukum','Legal Admin','Paralegal Assistant','Kriminologi');

-- Metadata sumber bobot prestasi.
ON DUPLICATE KEY UPDATE fungsi=VALUES(fungsi), is_active=VALUES(is_active);

-- View audit ringan untuk cek bobot dan coverage roadmap.
CREATE OR REPLACE VIEW `v_spk_weight_sum_check` AS
SELECT wp.tujuan_karir, wp.school_group, ROUND(SUM(cw.weight), 6) AS total_weight
FROM weight_profiles wp
JOIN criteria_weights cw ON cw.profile_id = wp.id
GROUP BY wp.tujuan_karir, wp.school_group;

CREATE OR REPLACE VIEW `v_alternative_roadmap_check` AS
SELECT a.id AS alternative_id, a.tujuan_karir, a.nama AS alternative_name, rm.id_roadmap, rm.title AS roadmap_title,
  CASE WHEN rm.id_roadmap IS NULL THEN 'MISSING_ROADMAP' ELSE 'OK' END AS status
FROM alternatives a
LEFT JOIN roadmap_master rm ON rm.id_roadmap = a.id;

-- Selesai V8.
